            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Why should you call me to account for eating decently? If I battened on the scorched corpses of animals, you might well ask me why I did that. Why should I be filthy and inhuman? Why should I be an accomplice in the wholesale horror and degradation of the slaughter-house?", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Just as the liar's punishment is, not in the least that he is not believed, but that he cannot believe any one else; so a guilty society can more easily be persuaded that any apparently innocent act is guilty than that any apparently guilty act is innocent.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The salvation of the world depends on the men who will not take evil good-humouredly, and whose laughter destroys the fool instead of encouraging him.", Author = "George Bernard Shaw" },
