            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The test of a man or woman's breeding is how they behave in a quarrel.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "People are always blaming circumstances for what they are. I don't believe in circumstances. The people who get on in this world are the people who get up and look for the circumstances they want, and, if they can't find them, make them.", Author = "George Bernard Shaw" },
