            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "You can always tell an old soldier by the inside of his holsters and cartridge boxes. The young ones carry pistols and cartridges; the old ones, grub.", Author = "George Bernard Shaw" },
