            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The worst sin towards our fellow creatures is not to hate them, but to be indifferent to them: that's the essence of inhumanity.", Author = "George Bernard Shaw" },
