            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "You must not suppose, because I am a man of letters, that I never tried to earn an honest living.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "It is a foolish expedient for making idle people believe they are doing something very clever, when they are only wasting their time.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "To understand a saint, you must hear the devil's advocate; and the same is true of the artist.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Assassination is the extreme form of censorship; and it seems hard to justify an incitement to it on anti-censorial principles.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The way to deal with worldly people is to frighten them by repeating their scandalous whisperings aloud.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "All very fine, Mary; but my old-fashioned common sense is better than your clever modern nonsense.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "If you leave your art, the world will beat you back to it. The world has not an ambition worth sharing, or a prize worth handling. Corrupt successes, disgraceful failures, or sheeplike vegetation are all it has to offer. I prefer Art, which gives me a sixth sense of beauty, with self-respect: perhaps also an immortal reputation in return for honest endeavour in a labour of love.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "A man's own self is the last person to believe in him, and is harder to cheat than the rest of the world.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Composers are not human; They can live on diminished sevenths, and be contented with a pianoforte for a wife, and a string quartet for a family.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Geniuses are horrid, intolerant, easily offended, sleeplessly self-conscious men, who expect their wives to be angels with no further business in life than to pet and worship their husbands. Even at the best they are not comfortable men to live with; and a perfect husband is one who is perfectly comfortable to live with.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Even the youngest of us may be wrong sometimes.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "This is the true joy in life, the being used for a purpose recognized by yourself as a mighty one; the being thoroughly worn out before you are thrown on the scrap heap; the being a force of Nature instead of a feverish selfish little clod of ailments and grievances complaining that the world will not devote itself to making you happy.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "There is no love sincerer than the love of food.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The only man I know who behaves sensibly is my tailor; he takes my measurements anew each time he sees me. The rest go on with their old measurements and expect me to fit them.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The confusion of marriage with morality has done more to destroy the conscience of the human race than any other single error.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Economy is the art of making the most of life. The love of economy is the root of all virtue.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Do not do unto others as you would expect they should do unto you. Their tastes may not be the same.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "If the lesser mind could measure the greater as a foot-rule can measure a pyramid, there would be finality in universal suffrage. As it is, the political problem remains unsolved.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Democracy substitutes election by the incompetent many for the corrupt few.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "He who confuses political liberty with freedom and political equality with similarity has never thought for five minutes about either.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Liberty means responsibility. That is why most men dread it.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The duke inquires contemptuously whether his gamekeeper is the equal of the Astronomer Royal; but he insists that they shall both be hanged equally if they murder him.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Where equality is undisputed, so also is subordination.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "A fool's brain digests philosophy into folly, science into superstition, and art into pedantry.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The best brought-up children are those who have seen their parents as they are. Hypocrisy is not the parent's first duty.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Every fool believes what his teachers tell him, and calls his credulity science or morality as confidently as his father called it divine revelation.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "No man can be a pure specialist without being in the strict sense an idiot.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The man who has graduated from the flogging block at Eton to the bench from which he sentences the garrotter to be flogged is the same social product as the garrotter who has been kicked by his father and cuffed by his mother until he has grown strong enough to throttle and rob the rich citizen whose money he desires.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Criminals do not die by the hands of the law. They die by the hands of other men.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "When a man wants to murder a tiger he calls it sport: when the tiger wants to murder him he calls it ferocity. The distinction between Crime and Justice is no greater.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "It is not necessary to replace a guillotined criminal: it is necessary to replace a guillotined social system.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "There are no perfectly honorable men; but every true man has one main point of honor and a few minor ones.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Beware of the man whose god is in the skies.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Self-denial is not a virtue: it is only the effect of prudence on rascality.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Obedience simulates subordination as fear of the police simulates honesty.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Disobedience, the rarest and most courageous of the virtues, is seldom distinguished from neglect, the laziest and commonest of the vices.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "In a stupid nation the man of genius becomes a god: everybody worships him and nobody does his will.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Happiness and Beauty are by-products.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Riches and Art are spurious receipts for the production of Happiness and Beauty.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "He who desires a lifetime of happiness with a beautiful woman desires to enjoy the taste of wine by keeping his mouth always full of it.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The man with a toothache thinks everyone happy whose teeth are sound. The poverty stricken man makes the same mistake about the rich man.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The more a man possesses over and above what he uses, the more careworn he becomes.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "In an ugly and unhappy world the richest man can purchase nothing but ugliness and unhappiness.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "No elaboration of physical or moral accomplishment can atone for the sin of parasitism.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The reasonable man adapts himself to the world: the unreasonable one persists in trying to adapt the world to himself. Therefore all progress depends on the unreasonable man.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Reason enslaves all whose minds are not strong enough to master her.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Decency is Indecency's Conspiracy of Silence.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Men are wise in proportion, not to their experience, but to their capacity for experience. If we could learn from mere experience, the stones of London would be wiser than its wisest men.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "No age or condition is without its heroes. The least incapable general in a nation is its Cæsar, the least imbecile statesman its Solon, the least confused thinker its Socrates, the least commonplace poet its Shakespeare.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The roulette table pays nobody except him that keeps it. Nevertheless a passion for gaming is common, though a passion for keeping roulette tables is unknown.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The reformer for whom the world is not good enough finds himself shoulder to shoulder with him that is not good enough for the world.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Youth, which is forgiven everything, forgives itself nothing: age, which forgives itself everything, is forgiven nothing.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Do not mistake your objection to defeat for an objection to fighting, your objection to being a slave for an objection to slavery, your objection to not being as rich as your neighbor for an objection to poverty. The cowardly, the insubordinate, and the envious share your objections.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Those who understand evil pardon it.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "When a heretic wishes to avoid martyrdom he speaks of \"Orthodoxy, True and False\" and demonstrates that the True is his heresy.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "If you begin by sacrificing yourself to those you love, you will end by hating those to whom you have sacrificed yourself.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The greatest of evils and the worst of crimes is poverty.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The faults of the burglar are the qualities of the financier: the manners and habits of a duke would cost a city clerk his situation.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "It is quite useless to declare that all men are born free if you deny that they are born good. Guarantee a man's goodness and his liberty will take care of itself. To guarantee his freedom on condition that you approve of his moral character is formally to abolish all freedom whatsoever, as every man's liberty is at the mercy of a moral indictment which any fool can trump up against everyone who violates custom, whether as a prophet or as a rascal.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Society, with all its prisons and bayonets and whips and ostracisms and starvations, is powerless in the face of the Anarchist who is prepared to sacrifice his own life in the battle with it. Our natural safety from the cheap and devastating explosives which every Russian student can make ... lies in the fact that brave and resolute men, when they are rascals, will not risk their skins for the good of humanity, and, when they are sympathetic enough to care for humanity, abhor murder, and never commit it until their consciences are outraged beyond endurance. The remedy is, then, simply not to outrage their consciences.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "I can't talk religion to a man with bodily hunger in his eyes.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "You cannot have power for good without having power for evil too. Even mother's milk nourishes murderers as well as heroes.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "My religion? Well, my dear, I am a Millionaire. That is my religion.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "You have learnt something. That always feels at first as if you had lost something.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "What is all human conduct but the daily and hourly sale of our souls for trifles?", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "He knows nothing; and he thinks he knows everything. That points clearly to a political career.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "A healthy nation is as unconscious of its nationality as a healthy man of his bones. But if you break a nation's nationality it will think of nothing else but getting it set again.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "You cannot be a hero without being a coward.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "What really flatters a man is that you think him worth flattering.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "My way of joking is to tell the truth. It's the funniest joke in the world.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "There is no subject on which more dangerous nonsense is talked and thought than marriage. If the mischief stopped at talking and thinking it would be bad enough; but it goes further, into disastrous anarchical action. Because our marriage law is inhuman and unreasonable to the point of downright abomination, the bolder and more rebellious spirits form illicit unions, defiantly sending cards round to their friends announcing what they have done. Young women come to me and ask me whether I think they ought to consent to marry the man they have decided to live with; and they are perplexed and astonished when I, who am supposed (heaven knows why!) to have the most advanced views attainable on the subject, urge them on no account to compromise themselves without the security of an authentic wedding ring.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Home life as we understand it is no more natural to us than a cage is natural to a cockatoo.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "When two people are under the influence of the most violent, most insane, most delusive, and most transient of passions, they are required to swear that they will remain in that excited, abnormal, and exhausting condition continuously until death do them part.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Plato long ago pointed out the importance of being governed by men with sufficient sense of responsibility and comprehension of public duties to be very reluctant to undertake the work of governing.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Love is an appetite which, like all other appetites, is destroyed for the moment by its gratification.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Never forget that if you leave your law to judges and your religion to bishops, you will presently find yourself without either law or religion.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Journalists are too poorly paid in this country to know anything that is fit for publication.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Monogamy has a sentimental basis which is quite distinct from the political one of equal numbers of the sexes. Equal numbers in the sexes are quite compatible with a change of partners every day or every hour. Physically there is nothing to distinguish human society from the farm-yard except that children are more troublesome and costly than chickens and calves, and that men and women are not so completely enslaved as farm stock. Accordingly, the people whose conception of marriage is a farm-yard or slave-quarter conception are always more or less in a panic lest the slightest relaxation of the marriage laws should utterly demoralize society; whilst those to whom marriage is a matter of more highly evolved sentiments and needs (sometimes said to be distinctively human, though birds and animals in a state of freedom evince them quite as touchingly as we) are much more liberal, knowing as they do that monogamy will take care of itself provided the parties are free enough, and that promiscuity is a product of slavery and not of liberty.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The secret of forgiving everything is to understand nothing.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Nothing is more dreadful than a husband who keeps telling you everything he thinks, and always wants to know what you think.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "All progress means war with Society.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The whole strength of England lies in the fact that the enormous majority of the English people are snobs.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "You don't learn to hold your own in the world by standing on guard, but by attacking, and getting well hammered yourself.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Religion is a great force — the only real motive force in the world; but what you fellows don't understand is that you must get at a man through his own religion and not through yours. Instead of facing that fact, you persist in trying to convert all men to your own little sect, so that you can use it against them afterwards. You are all missionaries and proselytizers trying to uproot the native religion from your neighbor's flowerbeds and plant your own in its place. You would rather let a child perish in ignorance than have it taught by a rival sectary. You can talk to me of the quintessential equality of coal merchants and British officers; and yet you can't see the quintessential equality of all the religions.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Why was I born with such contemporaries?", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "A critic recently described me, with deadly acuteness, as having 'a kindly dislike of my fellow-creatures.' Perhaps dread would have been nearer the mark than dislike; for man is the only animal of which I am thoroughly and cravenly afraid.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The word morality, if we met it in the Bible, would surprise us as much as the word telephone or motor car.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "That proves it's not by Shaw, because all Shaw's characters are himself: mere puppets stuck up to spout Shaw.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "As long as I have a want, I have a reason for living. Satisfaction is death.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Censorship ends in logical completeness when nobody is allowed to read any books except the books that nobody can read.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Custom will reconcile people to any atrocity; and fashion will drive them to acquire any custom.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "All great truths begin as blasphemies.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "You'll never have a quiet world till you knock the patriotism out of the human race.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "It is more dangerous to be a great prophet or poet than to promote twenty companies for swindling simple folk out of their savings.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Optimistic lies have such immense therapeutic value that a doctor who cannot tell them convincingly has mistaken his profession.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "A perpetual holiday is a good working definition of Hell.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "I like a bit of a mongrel myself, whether it's a man or a dog; they're the best for every day.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "If parents would only realize how they bore their children!", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "When will we realize that the fact that we can become accustomed to anything, however disgusting at first, makes it necessary to examine carefully everything we have become accustomed to.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "A nation should always be healthily rebellious; but the king or prime minister has yet to be found who will make trouble by cultivating that side of the national spirit. A child should begin to assert itself early, and shift for itself more and more not only in washing and dressing itself, but in opinions and conduct; yet as nothing is so exasperating and so unlovable as an uppish child, it is useless to expect parents and schoolmasters to inculcate this uppishness. Such unamiable precepts as Always contradict an authoritative statement, Always return a blow, Never lose a chance of a good fight, When you are scolded for a mistake ask the person who scolds you whether he or she supposes you did it on purpose, and follow the question with a blow or an insult or some other unmistakable expression of resentment, Remember that the progress of the world depends on your knowing better than your elders, are just as important as those of The Sermon on the Mount; but no one has yet seen them written up in letters of gold in a schoolroom or nursery.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "You are so careful of your boy's morals, knowing how troublesome they may be, that you keep him away from the Venus of Milo only to find him in the arms of the scullery maid or someone much worse. You decide that the Hermes of Praxiteles and Wagner's Tristan are not suited for young girls; and your daughter marries somebody appallingly unlike either Hermes or Tristan solely to escape from your parental protection. You have not stifled a single passion nor averted a single danger: you have depraved the passions by starving them, and broken down all the defences which so effectively protect children brought up in freedom.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The secret of being miserable is to have leisure to bother about whether you are happy or not. The cure for it is occupation, because occupation means pre-occupation; and the pre-occupied person is neither happy nor unhappy, but simply alive and active, which is pleasanter than any happiness until you are tired of it.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Do not try to live for ever. You will not succeed.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "No man who is occupied in doing a very difficult thing, and doing it well, ever loses his self-respect.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Attention and activity lead to mistakes as well as to successes; but a life spent in making mistakes is not only more honorable but more useful than a life spent doing nothing.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "All professions are conspiracies against the laity.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "I don't believe in morality. I'm a disciple of Bernard Shaw.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Life does not cease to be funny when people die any more than it ceases to be serious when people laugh.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Chloroform has done a lot of mischief. It's enabled every fool to be a surgeon.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Use your health, even to the point of wearing it out. That is what it is for. Spend all you have before you die; and do not outlive yourself.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "It is impossible for an Englishman to open his mouth without making some other Englishman hate or despise him.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The English have no respect for their language, and will not teach their children to speak it.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "He ain't a copper just look at 'is boots!", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Ah-ah-ah-ah-ow-ow-oo-oo!!! I ain't dirty: I washed me face and hands afore I come, I did!", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Women upset everything. When you let them into your life, you find that the woman is driving at one thing and you're driving at another.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "What is life but a series of inspired follies? The difficulty is to find them to do. Never lose a chance: it doesn't come every day.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "I wouldn't have ate it, only I'm too lady-like to take it out of my mouth.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "I don't want to talk grammar, I want to talk like a lady.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "I ask you, what am I? I'm one of the undeserving poor: thats what I am. Think of what that means to a man.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "I aint such a mug as to put up my children to all I know myself.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Walk! Not bloody likely. I am going in a taxi.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "I heard your prayers \"Thank God it's all over!\"", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "You see, lots of the real people can't do it at all: they're such fools that they think style comes by nature to people in their position; and so they never learn. There's always something professional about doing a thing superlatively well.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Time enough to think of the future when you haven't any future to think of.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "I have to live for others and not for myself; that's middle-class morality.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Independence? That's middle-class blasphemy. We are all dependent on one another, every soul of us on earth.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The fact that a believer is happier than a skeptic is no more to the point than the fact that a drunken man is happier than a sober one. The happiness of credulity is a cheap and dangerous quality of happiness, and by no means a necessity of life.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Revolutionary movements attract those who are not good enough for established institutions as well as those who are too good for them.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "No sooner had Jesus knocked over the dragon of superstition than Paul boldly set it on its legs again in the name of Jesus.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "waste is the law of modern war; and nothing is cheap on the battlefield except the lives of men...... Therefore, my taxpayer, resign yourself to this: that we may fight bravely, fight hard, fight long, fight cunningly, fight recklessly, fight in a hundred and fifty ways, but we cannot fight cheaply.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Has he attained the seventh degree of concentration?", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "We know now that the soul is the body, and the body the soul. They tell us they are different because they want to persuade us that we can keep our souls if we let them make slaves of our bodies.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "When your heart is broken, your boats are burned: nothing matters any more. It is the end of happiness and the beginning of peace.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "If people are fit to live, let them live under decent human conditions. If they are not fit to live, kill them in a decent human way. Is it any wonder that some of us are driven to prescribe the lethal chamber as the solution for the hard cases which are at present made the excuse for dragging all the other cases down to their level, and the only solution that will create a sense of full social responsibility in modern populations?", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "The Nazi movement is in many respects one which has my warmest sympathy.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Some of the things Mussolini has done, and some that he is threatening to do go further in the direction of Socialism than the English Labour Party could yet venture if they were in power.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Socialists must be in favor of an aristocratic form of government. We must have the best men for the job . . . In the dictator you must have a man who has not only the power to govern but the force of character to impose himself as dictator whether you like him or not.", Author = "George Bernard Shaw" },
            new Quote { Id = "https://en.wikiquote.org/wiki/George_Bernard_Shaw", Text = "Well, of course, they notice you. You always hide just in the middle of the limelight.", Author = "George Bernard Shaw" },
        };
    }
}